import{z as n,x as c,o,c as l,q as t,j as s,D as a,d as r,s as d,S as i}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"效应系统","description":"","frontmatter":{"title":"效应系统","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/effect-systems.md","filePath":"cs/effect-systems.md","lastUpdated":1791063341000}'),B={name:"cs/effect-systems.md"};function p(A,e,f,h,_,m){const E=c("Mermaid");return o(),l("div",null,[e[2]||(e[2]=t('<h1 id="效应系统" tabindex="-1">效应系统 <a class="header-anchor" href="#效应系统" aria-label="Permalink to &quot;效应系统&quot;">​</a></h1><div class="epigraph"><p>类型回答「值是什么」；效应回答「计算还做了什么」：抛异常、分配、IO、不确定。函数类型可带效应行，组合时取并。</p><footer>—— 据 Lucassen and Gifford, Polymorphic Effect Systems, 1988；Pierce TAPL 对效应的讨论；Leijen 行多态效应整理</footer></div><p>上一课<a href="/cs/lifetimes-regions">生命周期</a>跟踪指针活多久。缺口是<strong>计算的额外通道</strong>：<code>e : τ ! ε</code>。纯 STLC 的效应为空；<code>throw</code>、<code>print</code>、<code>alloc</code> 写入 ε。本课钉效应在类型上的位置，不把代数效应的全套 handler 语义写完。也不重写线性——线性管资源次数，效应管做了哪些动作。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HM 的 <code>a -&gt; a</code> 看不出会不会抛。Java 的 checked exception 是效应的粗粒度；ML 的 effect 系统（区域+读/写）服务优化与安全。缺口是<strong>函数类型上的 ε</strong>，以及子效应（少效应的函数可用在允许多效应的坑里——协变于效应集）。</p><p><span class="marginnote">术语翻译：<code>e : τ ! ε</code> 读作「表达式 e 算出一个 τ 类型的值，途中做了 ε 里列的动作」。ε 常写成集合：<code>{io}</code> 表示会做 IO，空集 <code>{}</code> 就是纯函数。可以类比商品标签：类型是「盒子里是什么」，效应行是「运输途中动用了哪些手段」。</span></p><p>行多态：<code>∀ρ. τ → τ ! {io | ρ}</code> 允许尚未点名的其它效应。这与<a href="/cs/typeclass-dictionary">类型类</a>的约束不同：效应常自动收集，不必实例搜索。</p><h3 id="效应不是「副作用」的散文同义词" tabindex="-1">效应不是「副作用」的散文同义词 <a class="header-anchor" href="#效应不是「副作用」的散文同义词" aria-label="Permalink to &quot;效应不是「副作用」的散文同义词&quot;">​</a></h3><p>未定义行为、数据竞争可以不在 ε 里。内存模型后课。本课的 ε 是语言声明的代数。</p><p><span class="marginnote">常见误区：把效应当成「副作用」的花哨叫法。散文里的副作用泛指一切外部影响；类型论里的 ε 是语言明文声明、机器可检查的清单。未定义行为、数据竞争这类「意外动作」并不在 ε 里——它们恰恰是效应系统想帮你排除的东西。</span></p><p><span class="marginnote">Lucassen–Gifford 1988。Talpin–Jouvelot。Koka / Eff / Frank 的代数效应是后继。Pierce 有短讨论。本课不把 Haskell <code>IO</code> 单子当唯一编码，尽管单子也能排效应序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规则：应用时合并两端效应；handler / <code>try</code> 从 ε 里减去已处理的标签。推断：与 W 同游，合一变成行合一（需处理 ρ）。优化：若 ε 空则可乱序或消除死代码（须健全）——中端课再用。</p>',13)),(o(),s(i,null,{default:a(()=>[d(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%CF%84%20%E2%86%92%20%CF%84'%20!%20%CE%B5%22%5D%20--%3E%20APP%5B%22%E5%BA%94%E7%94%A8%E5%B9%B6%E6%95%88%E5%BA%94%22%5D%0A%20%20APP%20--%3E%20H%5B%22handler%20%E5%87%8F%E5%8E%BB%E6%A0%87%E7%AD%BE%22%5D%0A%20%20H%20--%3E%20E2%5B%22%E5%89%A9%E4%BD%99%E6%95%88%E5%BA%94%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t('<p>与区域：分配效应可指到区域，Tofte 系统把二者绑在一起。点名对照。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>子类型：<code>ε ⊆ ε&#39;</code> 则带 ε 的计算可用在期望 ε&#39; 处。多态效应避免「所有函数都标 IO」。不要把 Java <code>throws Exception</code> 当行多态。</p><p><span class="marginnote">为什么重要：没有行多态，写一个「把参数转发给任意函数」的高阶工具就得把效应集合写死——每新增一种效应，全库签名跟着改。<code>∀ρ. τ → τ ! {io | ρ}</code> 里的 ρ 表示「还有未点名的其它效应」，让签名对未来保持开放。</span></p><p>带效应的函数，什么时候能放进另一个位置？</p>',5)),(o(),s(i,null,{default:a(()=>[d(E,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20F1%5B%22f%20%3A%20%CF%84%20%E2%86%92%20%CF%84'%20!%20%7Bio%7D%22%5D%20--%3E%20USE%7B%22%E8%B0%83%E7%94%A8%E5%A4%84%E6%9C%9F%E6%9C%9B%E7%9A%84%E6%95%88%E5%BA%94%E6%98%AF%E4%BB%80%E4%B9%88%3F%22%7D%0A%20%20USE%20--%3E%7C%22%E5%90%8C%E6%A0%B7%E6%9C%9F%E6%9C%9B%20%7Bio%7D%22%7C%20OK1%5B%22%E7%9B%B4%E6%8E%A5%E5%8F%AF%E7%94%A8%22%5D%0A%20%20USE%20--%3E%7C%22%E6%9C%9F%E6%9C%9B%20%CE%B5'%20%E4%B8%94%20%7Bio%7D%20%E2%8A%86%20%CE%B5'%22%7C%20OK2%5B%22%E5%8D%8F%E5%8F%98%E5%8F%AF%E7%94%A8%EF%BC%9A%E5%B0%91%E6%95%88%E5%BA%94%E6%94%BE%E8%BF%9B%E5%A4%9A%E6%95%88%E5%BA%94%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20USE%20--%3E%7C%22%E6%9C%9F%E6%9C%9B%E7%A9%BA%E9%9B%86%EF%BC%88%E7%BA%AF%E4%BD%8D%E7%BD%AE%EF%BC%89%22%7C%20NO%5B%22%E7%B1%BB%E5%9E%8B%E6%8B%92%E7%BB%9D%EF%BC%9A%E5%AE%83%E4%BC%9A%20IO%EF%BC%8C%E6%94%BE%E4%B8%8D%E8%BF%9B%E7%BA%AF%E4%BD%8D%E7%BD%AE%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<p>代数效应的续延实现接到运行时 CPS 课；本课只要类型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 handler 的深度语义。后课默认：函数类型可带效应行。下一课渐进类型：静态与动态的边界，效应与 tag 会相遇。</p><p>也不把「纯函数式编程」当已实现的效应系统。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>效应标注计算除结果外的动作；应用取并。</li><li>行多态避免把世界写成固定集合。</li><li>与线性、区域正交，可组合。</li><li>出处：Lucassen and Gifford, 1988；对照 Pierce；Leijen 行效应。</li></ul>',6))])}const u=n(B,[["render",p]]);export{D as __pageData,u as default};
